# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GEN TERAPİSİ SÜRECİ VE İNSAN GENOM PROJESİ</text>\n  <rect x="25" y="46" width="320" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Gen Terapisi Basamakları</text>\n  <rect x="42" y="84" width="286" height="32" rx="6" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="185" y="104" text-anchor="middle" font-size="11" fill="#1e3a8a">1. Sağlıklı (işlevsel) genin izole edilmesi</text>\n  <rect x="42" y="124" width="286" height="32" rx="6" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="185" y="144" text-anchor="middle" font-size="11" fill="#1e3a8a">2. Genin zararsız viral vektöre aktarılması</text>\n  <rect x="42" y="164" width="286" height="32" rx="6" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="185" y="184" text-anchor="middle" font-size="11" fill="#1e3a8a">3. Vektörün hastanın hedef hücrelerine verilmesi</text>\n  <text x="185" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Hedef: Normal protein sentezini başlatmak</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İnsan Genom Projesi (İGP)</text>\n  <text x="378" y="98" font-size="12" fill="#14532d">• <tspan font-weight="bold">Kapsam:</tspan> ~3 milyar baz çiftinin dizilimi</text>\n  <text x="378" y="122" font-size="12" fill="#14532d">• <tspan font-weight="bold">Gen Sayısı:</tspan> ~20.000 - 25.000 protein kodlayan gen</text>\n  <text x="378" y="146" font-size="12" fill="#14532d">• <tspan font-weight="bold">Benzerlik:</tspan> İnsanlar arası %99,9 baz benzerliği</text>\n  <text x="378" y="170" font-size="12" fill="#14532d">• <tspan font-weight="bold">Kazanım:</tspan> Hastalık genlerinin haritalanması</text>\n  <rect x="378" y="188" width="279" height="38" rx="6" fill="#f0fdf4" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="517" y="211" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kişiye özgü ilaç ve erken tanı imkânı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DNA PARMAK İZİ ANALİZİ VE JEL ELEKTROFOREZİ</text>\n  <rect x="25" y="46" width="310" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Uygulama Basamakları</text>\n  <text x="42" y="96" font-size="12" fill="#78350f">1. Hücreden saf <tspan font-weight="bold">DNA izolasyonu</tspan></text>\n  <text x="42" y="120" font-size="12" fill="#78350f">2. <tspan font-weight="bold">PCR</tspan> ile tekrar bölgelerinin çoğaltılması</text>\n  <text x="42" y="144" font-size="12" fill="#78350f">3. <tspan font-weight="bold">Restriksiyon enzimiyle</tspan> DNA kesimi</text>\n  <text x="42" y="168" font-size="12" fill="#78350f">4. <tspan font-weight="bold">Jel elektroforezinde</tspan> boyuta göre ayrım</text>\n  <text x="42" y="192" font-size="12" fill="#78350f">5. UV ışıkta <tspan font-weight="bold">bant profillerinin</tspan> karşılaştırılması</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Tek yumurta ikizlerinde bant dizilimi aynıdır!</text>\n  <rect x="355" y="46" width="320" height="196" rx="10" fill="#f1f5f9" stroke="#475569" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">Elektroforez Jel Bant Karşılaştırması</text>\n  <text x="405" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">Olay Yeri</text>\n  <text x="480" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">Şüpheli 1</text>\n  <text x="550" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Şüpheli 2</text>\n  <text x="620" y="88" text-anchor="middle" font-size="11" font-weight="bold" fill="#334155">Şüpheli 3</text>\n  <rect x="380" y="96" width="50" height="125" fill="#e2e8f0" stroke="#94a3b8"/>\n  <rect x="455" y="96" width="50" height="125" fill="#e2e8f0" stroke="#94a3b8"/>\n  <rect x="525" y="96" width="50" height="125" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <rect x="595" y="96" width="50" height="125" fill="#e2e8f0" stroke="#94a3b8"/>\n  <rect x="388" y="110" width="34" height="6" fill="#dc2626"/><rect x="388" y="145" width="34" height="6" fill="#dc2626"/><rect x="388" y="190" width="34" height="6" fill="#dc2626"/>\n  <rect x="463" y="122" width="34" height="6" fill="#334155"/><rect x="463" y="160" width="34" height="6" fill="#334155"/><rect x="463" y="202" width="34" height="6" fill="#334155"/>\n  <rect x="533" y="110" width="34" height="6" fill="#16a34a"/><rect x="533" y="145" width="34" height="6" fill="#16a34a"/><rect x="533" y="190" width="34" height="6" fill="#16a34a"/>\n  <rect x="603" y="110" width="34" height="6" fill="#334155"/><rect x="603" y="170" width="34" height="6" fill="#334155"/><rect x="603" y="205" width="34" height="6" fill="#334155"/>\n  <text x="515" y="234" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Eşleşme: Olay Yeri = Şüpheli 2 (%100 uyum)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KÖK HÜCRE KAYNAKLARI VE YAPAY ORGAN MÜHENDİSLİĞİ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">1. Embriyonik Kök Hücre</text>\n  <text x="40" y="98" font-size="11" fill="#581c87">• Blastosist evresinden alınır.</text>\n  <text x="40" y="120" font-size="11" fill="#581c87">• Dönüşüm yeteneği en yüksektir.</text>\n  <text x="40" y="142" font-size="11" fill="#581c87">• Tüm vücut hücrelerine dönüşür.</text>\n  <text x="40" y="164" font-size="11" fill="#581c87">• Biyoetik tartışmalara açıktır.</text>\n  <rect x="40" y="182" width="175" height="38" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="127" y="205" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Kapasite: Çok Yüksek</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">2. Kordon Kanı &amp; Yetişkin</text>\n  <text x="262" y="98" font-size="11" fill="#1e3a8a">• Göbek kordonu ve kırmızı</text>\n  <text x="270" y="114" font-size="11" fill="#1e3a8a">kemik iliğinden elde edilir.</text>\n  <text x="262" y="138" font-size="11" fill="#1e3a8a">• Dönüşüm yeteneği sınırlıdır.</text>\n  <text x="262" y="160" font-size="11" fill="#1e3a8a">• Lösemi ve kan hastalıklarında</text>\n  <text x="270" y="176" font-size="11" fill="#1e3a8a">yaygın olarak kullanılır.</text>\n  <rect x="262" y="188" width="175" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="349" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Etik sorun oluşturmaz</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. Yapay Doku ve Organ</text>\n  <text x="485" y="98" font-size="11" fill="#14532d">• Hastanın kendi kök hücresi</text>\n  <text x="493" y="114" font-size="11" fill="#14532d">+ 3B biyomateryal iskele</text>\n  <text x="485" y="138" font-size="11" fill="#14532d">• Yapay deri, kornea, kıkırdak</text>\n  <text x="485" y="160" font-size="11" fill="#14532d">• <tspan font-weight="bold">Avantaj:</tspan> Bağışıklık sistemi</text>\n  <text x="493" y="176" font-size="11" fill="#14532d">tarafından doku reddi olmaz.</text>\n  <rect x="485" y="188" width="175" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="572" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Organ bağışı ihtiyacını azaltır</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
